// The example corpus: one canonical snippet per margaui component, plus a
// synthesised stress case.
//
// assets/examples.json is generated by tools/gen-web-assets.mjs from margaui's
// playground. The "Kitchen sink" entry is built here by concatenating every
// snippet, which costs nothing to ship and is the interesting perf case: several
// hundred distinct candidates in one compile.

export const KITCHEN_SINK_ID = '__kitchen-sink'

export async function loadExamples(url = 'assets/examples.json') {
  const list = await fetch(url).then((response) => response.json())
  const byId = new Map(list.map((example) => [example.id, example]))
  const kitchenSink = {
    id: KITCHEN_SINK_ID,
    title: `Kitchen sink (${list.length} components)`,
    group: 'featured',
    file: null,
    get html() {
      return list
        .map((example) => `<!-- ${example.title} -->\n${example.html}`)
        .join('\n\n')
    },
  }
  byId.set(KITCHEN_SINK_ID, kitchenSink)
  return { list, byId, kitchenSink }
}

/** Fill a <select> with two optgroups: the featured components, then the rest. */
export function populateSelect(selectEl, examples) {
  const groups = [
    ['Featured', examples.list.filter((example) => example.group === 'featured')],
    ['All components', examples.list.filter((example) => example.group !== 'featured')],
  ]
  for (const [label, members] of groups) {
    if (members.length === 0) continue
    const group = document.createElement('optgroup')
    group.label = label
    for (const example of members) {
      const option = document.createElement('option')
      option.value = example.id
      option.textContent = example.title
      group.appendChild(option)
    }
    selectEl.appendChild(group)
  }
  const stress = document.createElement('optgroup')
  stress.label = 'Stress'
  const option = document.createElement('option')
  option.value = KITCHEN_SINK_ID
  option.textContent = examples.kitchenSink.title
  stress.appendChild(option)
  selectEl.appendChild(stress)
}
